 import logging
 import os
 import subprocess
 import threading
 import time
 from dataclasses import dataclass, field
 from typing import Any, Optional

 import requests

 logger = logging.getLogger("engine.mcp_tools.client")

 REQUEST_ID = 0


 def _next_id() -> int:
     global REQUEST_ID
     REQUEST_ID += 1
     return REQUEST_ID


 # ── Data types ──────────────────────────────────────────────────────────────

 @dataclass
 class MCPTool:
     name: str
     description: str = ""
     input_schema: dict = field(default_factory=dict)


 @dataclass
 class MCPResult:
     success: bool
     content: list[dict] = field(default_factory=list)
     error: str = ""


 # ── JSON-RPC helpers ────────────────────────────────────────────────────────

 def _make_request(method: str, params: dict = None) -> str:
     return json.dumps({
         "jsonrpc": "2.0",
         "id": _next_id(),
         "method": method,
         "params": params or {},
     })


 def _parse_response(raw: str) -> dict:
     data = json.loads(raw)
     if "error" in data and data["error"]:
         raise RuntimeError(data["error"].get("message", str(data["error"])))
     return data.get("result", data)


 # ── Content-Length framing (MCP stdio protocol) ────────────────────────────

 def _encode_message(body: str) -> bytes:
     encoded = body.encode("utf-8")
     return f"Content-Length: {len(encoded)}\r\nContent-Type: application/json\r\n\r\n".encode() + encoded


 def _decode_message(stream) -> Optional[str]:
     """Read one message from a binary stream.

     Handles two formats:
       1. Content-Length framing (MCP standard):
            Content-Length: N\r\n\r\n{body}
       2. JSON-line format (used by FastMCP servers):
            {json}\n

     Detects format by peeking at the first byte.
     """
     first_byte = stream.read(1)
     if not first_byte:
         return None

     # Peek: if it starts with '{', it's JSON-line format
     if first_byte == b'{':
         rest = stream.readline()
         raw = first_byte + rest
         return raw.decode("utf-8").strip()

     # Content-Length framing
     headers = {}
     line = first_byte + stream.readline()
     while line:
         line = line.strip()
         if isinstance(line, bytes):
             line = line.decode("utf-8")
         if not line:
             break
         if ":" in line:
             key, val = line.split(":", 1)
             headers[key.strip().lower()] = val.strip()
         line = stream.readline()
     length = int(headers.get("content-length", 0))
     if length == 0:
         return None
     body = stream.read(length)
     if isinstance(body, bytes):
         body = body.decode("utf-8")
     return body


